const cx = (...c: (string | false | null | undefined)[]) => c.filter(Boolean).join(" ");

const API_STATUS_SVG = `<svg class="sf-api-status" xmlns="http://www.w3.org/2000/svg" width="720" height="460" viewBox="0 0 720 460" fill="none" stroke="#1daf9c" role="img" aria-labelledby="sf-api-status-t" aria-describedby="sf-api-status-d">
